//! ML-DSA-44/65 known-answer fixtures and case runner for the SHA-34 benchmarks.
//!
//! The fixtures under `fixtures/` are generated by `scripts/gen_mldsa_vectors.py` from
//! pinned NIST ACVP and Wycheproof vectors (see `fixtures/MANIFEST.json`). This crate
//! parses them without allocation or panics and runs each case through `ml-dsa`'s pure
//! FIPS 204 verify, so the same code runs in the host KATs and on the boards.
//!
//! Fixture format (little-endian):
//!
//! ```text
//! header:   b"KSMD", u16 param set (44 or 65), u16 case count
//! per case: u32 tc_id, u8 source (0 = ACVP, 1 = Wycheproof), u8 expect_valid (0 or 1),
//!           u16 ctx_len, u32 msg_len, u16 pk_len, u16 sig_len,
//!           then ctx, msg, pk and sig bytes
//! ```
#![no_std]
#![forbid(unsafe_code)]

#[cfg(feature = "cortex-m")]
pub mod measure;

pub use ml_dsa::{MlDsa44, MlDsa65, MlDsaParams};

use ml_dsa::{EncodedSignature, EncodedVerifyingKey, Signature, VerifyingKey};

/// Fixture magic bytes.
pub const MAGIC: [u8; 4] = *b"KSMD";

/// On-target ML-DSA-44 fixture: all ACVP valid cases, one invalid case per ACVP reason and
/// the Wycheproof advisory regression cases.
pub const MLDSA44_TARGET: &[u8] = include_bytes!("../fixtures/mldsa44-target.bin");

/// On-target ML-DSA-65 fixture (same selection as [`MLDSA44_TARGET`]).
pub const MLDSA65_TARGET: &[u8] = include_bytes!("../fixtures/mldsa65-target.bin");

/// An ML-DSA parameter set covered by the fixtures.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ParamSet {
    MlDsa44,
    MlDsa65,
}

impl ParamSet {
    /// The number used in the fixture header and in `ML-DSA-<n>`.
    pub const fn number(self) -> u16 {
        match self {
            ParamSet::MlDsa44 => 44,
            ParamSet::MlDsa65 => 65,
        }
    }
}

/// Where a case comes from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Source {
    /// NIST ACVP-Server ML-DSA-sigVer-FIPS204, external interface, pure.
    Acvp,
    /// C2SP Wycheproof `mldsa_*_verify_test.json`.
    Wycheproof,
}

impl Source {
    /// Short name used in logs.
    pub const fn name(self) -> &'static str {
        match self {
            Source::Acvp => "acvp",
            Source::Wycheproof => "wycheproof",
        }
    }
}

/// Why a fixture could not be parsed.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ParseError {
    /// The fixture does not start with [`MAGIC`].
    BadMagic,
    /// The header names a parameter set other than 44 or 65.
    UnknownParamSet(u16),
    /// A case has a source byte other than 0 or 1.
    UnknownSource(u8),
    /// A case has an `expect_valid` byte other than 0 or 1.
    BadExpectation(u8),
    /// The input ends inside a header or a case.
    Truncated,
    /// Bytes remain after the declared number of cases.
    TrailingBytes,
    /// The fixture is for a different parameter set than the caller asked for.
    WrongParamSet(ParamSet),
}

/// One known-answer case, borrowing its bytes from the fixture.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Case<'a> {
    pub tc_id: u32,
    pub source: Source,
    pub expect_valid: bool,
    pub ctx: &'a [u8],
    pub msg: &'a [u8],
    pub pk: &'a [u8],
    pub sig: &'a [u8],
}

/// A parsed fixture header plus the undecoded case bytes.
#[derive(Clone, Copy, Debug)]
pub struct Fixture<'a> {
    pub param_set: ParamSet,
    pub count: u16,
    body: &'a [u8],
}

impl<'a> Fixture<'a> {
    /// Parses the fixture header. The cases are decoded lazily by [`Fixture::cases`].
    pub fn parse(bytes: &'a [u8]) -> Result<Self, ParseError> {
        let mut rest = bytes;
        if take(&mut rest, MAGIC.len())? != MAGIC.as_slice() {
            return Err(ParseError::BadMagic);
        }
        let param_set = match read_u16(&mut rest)? {
            44 => ParamSet::MlDsa44,
            65 => ParamSet::MlDsa65,
            other => return Err(ParseError::UnknownParamSet(other)),
        };
        let count = read_u16(&mut rest)?;
        Ok(Self {
            param_set,
            count,
            body: rest,
        })
    }

    /// Iterates over the cases. After the first error the iterator ends.
    pub fn cases(&self) -> Cases<'a> {
        Cases {
            rest: self.body,
            remaining: self.count,
            done: false,
        }
    }
}

/// Iterator over the cases of a [`Fixture`].
#[derive(Clone, Debug)]
pub struct Cases<'a> {
    rest: &'a [u8],
    remaining: u16,
    done: bool,
}

impl<'a> Iterator for Cases<'a> {
    type Item = Result<Case<'a>, ParseError>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.done {
            return None;
        }
        if self.remaining == 0 {
            self.done = true;
            return (!self.rest.is_empty()).then_some(Err(ParseError::TrailingBytes));
        }
        self.remaining -= 1;
        let case = parse_case(&mut self.rest);
        if case.is_err() {
            self.done = true;
        }
        Some(case)
    }
}

fn parse_case<'a>(rest: &mut &'a [u8]) -> Result<Case<'a>, ParseError> {
    let tc_id = read_u32(rest)?;
    let source = match read_u8(rest)? {
        0 => Source::Acvp,
        1 => Source::Wycheproof,
        other => return Err(ParseError::UnknownSource(other)),
    };
    let expect_valid = match read_u8(rest)? {
        0 => false,
        1 => true,
        other => return Err(ParseError::BadExpectation(other)),
    };
    let ctx_len = usize::from(read_u16(rest)?);
    let msg_len = usize::try_from(read_u32(rest)?).map_err(|_| ParseError::Truncated)?;
    let pk_len = usize::from(read_u16(rest)?);
    let sig_len = usize::from(read_u16(rest)?);
    Ok(Case {
        tc_id,
        source,
        expect_valid,
        ctx: take(rest, ctx_len)?,
        msg: take(rest, msg_len)?,
        pk: take(rest, pk_len)?,
        sig: take(rest, sig_len)?,
    })
}

fn take<'a>(rest: &mut &'a [u8], n: usize) -> Result<&'a [u8], ParseError> {
    let (head, tail) = rest.split_at_checked(n).ok_or(ParseError::Truncated)?;
    *rest = tail;
    Ok(head)
}

fn read_u8(rest: &mut &[u8]) -> Result<u8, ParseError> {
    let [b] = take_array::<1>(rest)?;
    Ok(b)
}

fn read_u16(rest: &mut &[u8]) -> Result<u16, ParseError> {
    take_array(rest).map(u16::from_le_bytes)
}

fn read_u32(rest: &mut &[u8]) -> Result<u32, ParseError> {
    take_array(rest).map(u32::from_le_bytes)
}

fn take_array<const N: usize>(rest: &mut &[u8]) -> Result<[u8; N], ParseError> {
    <[u8; N]>::try_from(take(rest, N)?).map_err(|_| ParseError::Truncated)
}

/// Verifies one case with `ml-dsa`'s pure FIPS 204 `ML-DSA.Verify` (Algorithm 3).
///
/// A public key or signature of the wrong length, a signature that does not decode
/// (for example malformed hints) and a context longer than 255 bytes all count as
/// "invalid", i.e. `false`.
#[inline(never)]
pub fn verify_case<P: MlDsaParams>(case: &Case<'_>) -> bool {
    let Ok(vk_enc) = EncodedVerifyingKey::<P>::try_from(case.pk) else {
        return false;
    };
    let Ok(sig_enc) = EncodedSignature::<P>::try_from(case.sig) else {
        return false;
    };
    let Some(sig) = Signature::<P>::decode(&sig_enc) else {
        return false;
    };
    VerifyingKey::<P>::decode(&vk_enc).verify_with_context(case.msg, case.ctx, &sig)
}

/// Verifies `case` with the parameter set named by its fixture.
pub fn verify_for(param_set: ParamSet, case: &Case<'_>) -> bool {
    match param_set {
        ParamSet::MlDsa44 => verify_case::<MlDsa44>(case),
        ParamSet::MlDsa65 => verify_case::<MlDsa65>(case),
    }
}

/// The result of running one case.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Outcome {
    pub tc_id: u32,
    pub source: Source,
    pub expected_valid: bool,
    pub verified: bool,
}

impl Outcome {
    /// Compares a verification result with the case's expectation.
    pub fn new(case: &Case<'_>, verified: bool) -> Self {
        Self {
            tc_id: case.tc_id,
            source: case.source,
            expected_valid: case.expect_valid,
            verified,
        }
    }

    /// True when the verification result matches the expectation.
    pub fn passed(&self) -> bool {
        self.expected_valid == self.verified
    }
}

/// Totals for a whole fixture run.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Summary {
    pub total: u32,
    pub passed: u32,
    /// The first case whose result did not match its expectation.
    pub first_failure: Option<Outcome>,
}

impl Summary {
    /// Records one outcome.
    pub fn record(&mut self, outcome: Outcome) {
        self.total = self.total.saturating_add(1);
        if outcome.passed() {
            self.passed = self.passed.saturating_add(1);
        } else if self.first_failure.is_none() {
            self.first_failure = Some(outcome);
        }
    }

    /// True when at least one case ran and every case matched its expectation.
    pub fn all_passed(&self) -> bool {
        self.total > 0 && self.passed == self.total
    }
}

/// Runs every case of `fixture`, calling `on_case` with each outcome, and checks that the
/// fixture holds `expected` cases.
pub fn run_fixture(
    bytes: &[u8],
    expected: ParamSet,
    mut on_case: impl FnMut(&Case<'_>, &Outcome),
) -> Result<Summary, ParseError> {
    let fixture = Fixture::parse(bytes)?;
    if fixture.param_set != expected {
        return Err(ParseError::WrongParamSet(fixture.param_set));
    }
    let mut summary = Summary::default();
    for case in fixture.cases() {
        let case = case?;
        let outcome = Outcome::new(&case, verify_for(fixture.param_set, &case));
        on_case(&case, &outcome);
        summary.record(outcome);
    }
    Ok(summary)
}
